use std::fs
use std::env

fn emit(text: string, number: bool, counter: int) -> int {
    if !number {
        print(text)
        return counter
    }
    let parts: Vec<string> = text.split("\n").collect()
    let mut n: int = parts.len() as int
    if n > 0 && parts[(n - 1) as usize] == "" {
        n = n - 1
    }
    let mut c = counter
    let mut i: int = 0
    while i < n {
        c = c + 1
        let mut s = "${c}"
        while s.len() < 6 {
            s = " " + s
        }
        println("${s}\t${parts[i as usize]}")
        i = i + 1
    }
    c
}

fn main() {
    let mut number = false
    let mut files: Vec<string> = []
    let mut first = true
    for a in env::args() {
        if first {
            first = false
            continue
        }
        if a == "-n" {
            number = true
        } else {
            files.push(a)
        }
    }
    let mut counter: int = 0
    let mut status: int = 0
    if files.len() == 0 {
        let text = fs::read_to_string("/dev/stdin").unwrap_or("")
        counter = emit(text, number, counter)
    } else {
        for f in files {
            match fs::read_to_string(f) {
                Ok(t) => {
                    counter = emit(t, number, counter)
                }
                Err(_) => {
                    println("cat: ${f}: No such file")
                    status = 1
                }
            }
        }
    }
    if status != 0 {
        std::process::exit(1)
    }
}
